<template>
  <div ref="canvasContainer" class="canvas-container"></div>
  <div class="loading-box" v-if="loading">
    <el-progress :percentage="percent" :stroke-width="26" :text-inside="true" color="#000000" />
  </div>
  <div class="btn-box">
    <el-button @click="reset" plain round>重置</el-button>
    <el-button @click="hiddenAlarm" plain round type="danger">报警</el-button>
  </div>
</template>

<script setup lang="ts">
import { ref } from "vue";
import * as THREE from "three";
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { onMounted } from "vue";
import TWEEN, { Tween } from "@tweenjs/tween.js";

const canvasContainer = ref<HTMLDivElement | null>(null)
let scene: THREE.Scene
let camera: THREE.PerspectiveCamera
let controls: OrbitControls
let raycaster: THREE.Raycaster
let tween: Tween = new TWEEN.Tween({});
let tween1: Tween = new TWEEN.Tween({});
let apertureMaterial: THREE.ShaderMaterial
let render: THREE.WebGLRenderer
let loading = ref<Boolean>(true)
let ring: THREE.Mesh
const percent = ref<string>('0')

// 初始化场景
const initScene = () => {
  // 创建场景
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x000000);

  // 创建相机
  camera = new THREE.PerspectiveCamera(
    50,
    window.innerWidth / window.innerHeight,
    0.1,
    5000
  );
  camera.position.set(-1, 1, -1);

  // 创建渲染器
  render = new THREE.WebGLRenderer({ antialias: true }); // antialias: true 开启抗锯齿
  render.setSize(window.innerWidth, window.innerHeight); // 设置渲染区域尺寸，以浏览器窗口宽高为尺寸
  canvasContainer?.value?.appendChild(render.domElement); // 将渲染器的dom元素添加到html中

  // 添加光源
  const ambientLight: THREE.AmbientLight = new THREE.AmbientLight(0xffffff, 0.5);
  scene.add(ambientLight);
  const directionalLight: THREE.PointLight = new THREE.PointLight(0xffffff, 1, 100);
  directionalLight.position.set(0, 10, 10);
  scene.add(directionalLight);

  // 添加轨道控制器
  controls = new OrbitControls(camera, render.domElement);

  // 基础配置
  controls.enableDamping = true; // 启用阻尼（惯性效果）
  controls.dampingFactor = 0.05; // 阻尼系数
  controls.enableZoom = true; // 启用缩放
  controls.enablePan = true; // 启用平移
  controls.enableRotate = true; // 启用拖拽旋转
  controls.zoomToCursor = true; // 允许缩放到鼠标位置

  // 创建射线检测器
  raycaster = new THREE.Raycaster();

  // 监听窗口变化，更新渲染器尺寸
  window.addEventListener("resize", () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    render.setSize(window.innerWidth, window.innerHeight);
  });

  // 监听鼠标点击事件
  window.addEventListener("click", onSceneClick);

  const gltfLoader = new GLTFLoader(manager);
  // 引入主模型
  //const loader: GLTFLoader = gltfLoader(manager);
  gltfLoader.load("static/models/city.glb", (gltf) => {
    const model = gltf.scene;
    model.scale.set(15, 15, 15);
    scene.add(model);
  });

  // 引入模型2
  //const loader2: GLTFLoader = new GLTFLoader();
  gltfLoader.load("static/models/icon.glb", (gltf) => {
    const model: THREE.Object3D = gltf.scene;
    model.scale.set(0.01, 0.01, 0.01);
    model.position.set(0.2, 0.6, 0.36);
    model.rotation.set(0, (Math.PI / 2) * 3, 0);
    scene.add(model);
  });
  setAperture()
  animate();
};

const manager = new THREE.LoadingManager(
  // 加载完成回调
  () => {
    setTimeout(()=>{
      loading.value = false
    }, 1000)
    animate();
  },
  // 加载进度回调
  (url, loaded, total) => {
    percent.value = (loaded / total * 100).toFixed(0);
  },
  // 加载错误回调
  (url) => {
    console.error('Error loading:', url);
  }
);


// 动画循环
const animate = () => {
  requestAnimationFrame(animate);
  controls.update();
  // 聚焦动画
  tween.update();
  tween1.update();
  // 报警闪烁
  apertureMaterial.uniforms.time.value = performance.now() * 0.001;
  render.render(scene, camera);
};

// 报警光圈特效
const setAperture = () => {
  // 创建圆形平面几何体（光圈形状）
  const aperture = new THREE.CircleGeometry(0.1, 64); // 半径1，分段数64

  // 定义动态材质（实现闪烁效果）
  apertureMaterial = new THREE.ShaderMaterial({
    uniforms: {
      time: { value: 0 },          // 时间变量控制闪烁
      color: { value: new THREE.Color(0xff0000) }, // 红色主色调
      intensity: { value: 1.5 }     // 光强系数
    },
    transparent: true,
    blending: THREE.AdditiveBlending, // 加法混合增强发光效果
    vertexShader: `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform float time;
      uniform vec3 color;
      uniform float intensity;
      varying vec2 vUv;
      
      void main() {
        // 计算距离中心的长度（0-1）
        float distance = length(vUv - vec2(0.5));
        // 边缘虚化效果（基于距离的指数衰减）
        float falloff = exp(-10.0 * distance * distance);
        // 透明度波动（基于时间的正弦变化）
        float alpha = (sin(time * 4.0) * 0.5 + 0.5) * falloff;
        // 输出颜色（颜色强度叠加动态透明度）
        gl_FragColor = vec4(color * intensity, alpha);
      }
    `
  });

  // 创建光圈对象并居中
  ring = new THREE.Mesh(aperture, apertureMaterial);
  ring.position.set(0, 0.1, 0);
  ring.rotation.x = -Math.PI / 2;
}

// 点击事件整合
const onSceneClick = (event: MouseEvent) => {
  event.stopPropagation();

  const mouse = new THREE.Vector2();
  mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  const intersects = raycaster.intersectObjects(scene.children);
  if (intersects.length > 0) {
    const intersection: THREE.Intersection | undefined = intersects.find((i) => i.object.name);
    if (
      intersection?.object.name === "Cube" ||
      /Building/.test(intersection?.object.name as string)
    ) {
      startCameraAnimation(intersection?.point);
    }
  }
};

interface Position {
  x: number | undefined;
  y: number;
  z: number;
  [key: string]: any;
}

// 聚焦到某个坐标
const startCameraAnimation = (targetPosition: THREE.Vector3 | undefined) => {
  if (!targetPosition) return;
  // 移动摄像头位置，实现聚焦功能
  let position: Position = {
    x: targetPosition.x,
    y: targetPosition.y + 1,
    z: targetPosition.z + 1
  };
  tween = new TWEEN.Tween(camera.position)
    .to(position, 1500)
    .easing(TWEEN.Easing.Sinusoidal.InOut)
    .start()
  tween1 = new TWEEN.Tween(controls.target)
    .to({ ...targetPosition, rotate: 90 }, 1500)
    .easing(TWEEN.Easing.Sinusoidal.InOut)
    .start();
};

// 重置
const reset = () => {
  controls.reset()
  ring.visible = false
}

// 切换报警展示
const hiddenAlarm = () => {
  if(!scene.children.includes(ring)) {
    scene.add(ring)
  } else {
    ring.visible = !ring.visible
  }
}

onMounted(() => {
  initScene();
});

</script>

<style lang="scss" scoped>
@use "../assets/styles/dashboard/dashboard.scss";
</style>