import request from "./request";

export const getData = (url: string, params: object): Promise<any> => {
  return request({
    method: "get",
    url,
    params
  })
};

export const postData = (url: string, data: object): Promise<any> => {
  return request({
    method: "post",
    url,
    data
  })
};

export const putData = (url: string, data: object): Promise<any> => {
  return request({
    method: "put",
    url,
    data
  })
};

export const deleteData = (url: string, data: object): Promise<any> => {
  return request({
    method: "delete",
    url,
    data
  })
};