<template>
  <div class="diaital-box">
    <!--<div class='timerBox'>
      <div class="_div">
        <div class="box1">{{ currentTime }}</div>
        <div class="box2">{{ currentDate }}&nbsp;&nbsp;{{ week }}</div>
      </div>
    </div>-->
    <div class="left-sides sides">
      <div class="item mb-10">
        <div class="title people">人员统计</div>
        <div class="cont people-cont">
          <div class="num-box">
            <div class="_div">
              <div class="t">
                <svg data-v-d2e47025="" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><path fill="currentColor" d="M384 192v640l384-320.064z"></path></svg>
                &nbsp;今日通行人数
              </div>
              <div class="l"><span>{{ sumPerson }}</span> 位</div>
            </div>
            <div class="_div">
              <div class="t">
                <svg data-v-d2e47025="" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><path fill="currentColor" d="M384 192v640l384-320.064z"></path></svg>
                &nbsp;进场总人数
              </div>
              <div class="l"><span>{{ inCount }}</span> 位</div>
            </div>
            <div class="_div">
              <div class="t">
                <svg data-v-d2e47025="" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024"><path fill="currentColor" d="M384 192v640l384-320.064z"></path></svg>
                &nbsp;出场总人数
              </div>
              <div class="l"><span>{{ outCount }}</span> 位</div>
            </div>
          </div>
          <div class="namal-box">
            <div class="hdiv">
              <div class="t mb-10">通行方式</div>
              <div class="boxs" id="transMethodEle"></div>
            </div>
            <div class="hdiv">
              <div class="t mb-10">人员类型</div>
              <div class="boxs" id="personTypeEle"></div>
            </div>
          </div>
        </div>
      </div>
      <div class="item">
        <div class="title car">车辆统计</div>
        <div class="cont car-cont">
          <div class="common_boxs common_boxs_1">
            <div class="c_box">
              <div class="lst mb-5">
                <img src="@/assets/images/screen/p.png" />
                <div class="r_label">
                  <div class="mt-5 mb-10">总车位数（个）</div>
                  <div>{{ sumStop }}</div>
                </div>
              </div>
              <div class="lst">
                <img src="@/assets/images/screen/p.png" />
                <div class="r_label">
                  <div class="mt-5 mb-10">今日出场数（个）</div>
                  <div>{{ outStop }}</div>
                </div>
              </div>
            </div>
            <div class="c_box">
              <div class="lst mb-5">
                <img src="@/assets/images/screen/p.png" />
                <div class="r_label">
                  <div class="mt-5 mb-10">剩余车位数（个）</div>
                  <div>{{ remainStop }}</div>
                </div>
              </div>
              <div class="lst">
                <img src="@/assets/images/screen/p.png" />
                <div class="r_label">
                  <div class="mt-5 mb-10">今日入场数（个）</div>
                  <div>{{ inStop }}</div>
                </div>
              </div>
            </div>
          </div>
          <div class="namal-box mb-10">
            <div class="hdiv">
              <div class="t mb-10">今日车辆类型数量</div>
              <div class="car_count">
                <div class="stem month"><div class="shuju">{{ carData[0]['value'] }}<span>/辆</span></div></div>
                <div class="stem temp"><div class="shuju">{{ carData[1]['value'] }}<span>/辆</span></div></div>
              </div>
            </div>
            <div class="hdiv">
              <div class="t mb-10">今日车辆类型占比</div>
              <div class="car_chart" id="carChartEle">111111</div>
            </div>
          </div>
          <div class="n_title mb-10 c-fff">最新入场记录</div>
          <div class="car_records_box">
            <div class="car_list _head">
              <div class="th width_1">出入场</div>
              <div class="th width_1">车牌号</div>
              <div class="th width_2">通行时间</div>
              <div class="th width_1">车辆类型</div>
            </div>
            <div class="car_list _body" :class="{'w1':screenPixel>1920}">
              <template v-if="carRecordList && carRecordList.length>0">
                <div class="item_record cursor" v-for="(item,index) in carRecordList" :key="'car_'+index">
                  <div class="th width_1"><span class="dot" :class="{out:item.status!=1}"></span>&nbsp;{{ item.status===1 ? '入场':'出场' }}</div>
                  <div class="th width_1">{{ item.plateNum }}</div>
                  <div class="th width_2">{{ item.transitTime }}</div>
                  <div class="th width_1">{{ item.type }}</div>
                </div>
              </template>
              <template v-else>
                <div class="c-fff"><el-empty :image-size="75" description="暂无数据"></el-empty></div>
              </template>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="right-sides sides">
      <div class="item mb-10">
        <div class="title device">设备统计</div>
        <div class="cont device-cont">
          <div class="common_boxs common_boxs_2">
            <div class="c_box" id="devCharts"></div>
            <div class="c_box">
              <div class="lst mb-10">
                <div class="r_label">
                  <div class="mt-10">在线设备数</div>
                  <div>{{ onlineCount }}</div>
                </div>
              </div>
              <div class="lst">
                <div class="r_label">
                  <div class="mt-10">故障设备数</div>
                  <div>{{ offlineCount }}</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="item mb-10">
        <div class="title power">水电消耗</div>
        <div class="cont power-cont">
          <div class="n_title mb-10 c-fff">本月/当日用水量
            <span class="c_b4c f-12 float-r">较上月用水量&nbsp;
              <span class="c-fff f-14">{{ lastMonthWeter }}（吨）</span>&nbsp;
              <span class="c_e2f f-12">环比</span>&nbsp;
              <template v-if="lastMonthWeterComp>0">
                <span class="c_ff2 f-12">{{ lastMonthWeterComp }}%</span>
                <img src="@/assets/images/screen/up.png" />
              </template>
              <template v-else>
                <span class="c_73d f-12">{{ lastMonthWeterComp }}%</span>
                <img src="@/assets/images/screen/down.png" />
              </template>
            </span>
          </div>
          <div class="power-chart-div mb-10">
            <div class="item_left">
              <div class="weter-div slide-1" id="weterMonthEle"></div>
              <div class="weter-div slide-2" id="weterDayEle"></div>
            </div>
            <div class="item_right weter mt-20">
              <div class="c_b4c f-12 mb-10">年度累计用水量</div>
              <div class="c-fff f-20">{{ yearWeter }}<span class="f-12">（吨）</span></div>
            </div>
          </div>
          <div class="n_title mb-10 c-fff">本月/当日用电量
            <span class="c_b4c f-12 float-r">较上月用电量&nbsp;
              <span class="c-fff f-14">{{ lastMonthElectirc }}KV/H</span>&nbsp;&nbsp;
              <span class="c_e2f f-12">环比</span>&nbsp;
              <template v-if="lastMonthElectircComp>0">
                <span class="c_ff2 f-12">{{ lastMonthElectircComp }}%</span>
                <img src="@/assets/images/screen/up.png" />
              </template>
              <template v-else>
                <span class="c_73d f-12">{{ lastMonthElectircComp }}%</span>
                <img src="@/assets/images/screen/down.png" />
              </template>
            </span>
          </div>
          <div class="power-chart-div mb-10">
            <div class="item_left">
              <div class="weter-div slide-3" id="eleMonthEle"></div>
              <div class="weter-div slide-4" id="eleDayEle"></div>
            </div>
            <div class="item_right electricity mt-20">
              <div class="c_b4c f-12 mb-10">年度累计用电量</div>
              <div class="c-fff f-20">{{ yearElectirc }}<span class="f-12">（KV/h）</span></div>
            </div>
          </div>
        </div>
      </div>
      <div class="item">
        <div class="title alarm">最新告警信息</div>
        <div class="cont alarm-cont" :class="{'height1':screenPixel>1920}">
          <template v-if="alarmList && alarmList.length>0">
            <div class="warn_item mb-5 cursor" v-for="(item,index) in alarmList" :key="'alarm_'+index">
              <div class="info">
                <div class="position f-14 mb-10">{{ item.deviceName }}<span class="c-fff">·创新园d坐北{{ index+1 }}</span></div>
                <div class="time f-14">{{ item.alarmTime }}</div>
                <div class="status f-16">{{ item.state==0 ? '待确认':(item.state==1 ? '待处理':'已处理') }}</div>
              </div>
            </div>
          </template>
          <template v-else>
            <div class="c-fff"><el-empty :image-size="140" description="暂无数据"></el-empty></div>
          </template>
        </div>
      </div>
    </div>
    <DashBoard />
  </div>
</template>

<script setup>
  import echarts from 'echarts'
  import { ref, onMounted, onBeforeUnmount } from 'vue'
  import { getData, postData } from "@/api/index";
  import DashBoard from './dashboard.vue';
  import '../assets/styles/chart.scss'

  let timer = null;
  let screenPixel = ref(1080);
  let deviceTotal = ref(0); // 设备总数
  let onlineCount = ref(0); // 设备在线总数
  let offlineCount = ref(0); // 设备故障总数
  let transMethodChart = null;
  let personTypeChart = null;
  let carChart = null;
  let deviceChart = null;
  let weterMonthChart = null;
  let weterDayChart = null;
  let electricMonthChart = null;
  let electricDayChart = null;
  let carRecordList = ref([
    { status: 1, plateNum: '京A12345', transitTime: '2025-05-15 15:05:10', type:'月租车' },
    { status: 0, plateNum: '沪BAB888', transitTime: '2025-05-15 16:06:20', type:'临时车' },
    { status: 0, plateNum: '粤Z9999港', transitTime: '2025-05-15 17:07:30', type:'月租车' },
    { status: 1, plateNum: '苏E5W6X7', transitTime: '2025-05-15 18:08:35', type:'月租车' },
    { status: 0, plateNum: '沪BAB888', transitTime: '2025-05-15 16:06:20', type:'临时车' },
    { status: 0, plateNum: '粤Z9999港', transitTime: '2025-05-15 17:07:30', type:'月租车' },
  ])
  let transMethodData = ref([
    { value: parseInt(100 * (Math.random()+1)), name: '二维码', type:'qr' },
    { value: parseInt(200  * (Math.random()+1)), name: '人脸', type:'face' },
    { value: parseInt(300  * (Math.random()+1)), name: '刷卡', type:'card' }
  ])
  let personTypeData = ref([
    { value: parseInt(100 * (Math.random()+1)), name: '业主', type:'owner' },
    { value: parseInt(200  * (Math.random()+1)), name: '访客', type:'visitor' },
    { value: parseInt(300  * (Math.random()+1)), name: '物管', type:'manager' },
    { value: parseInt(300  * (Math.random()+1)), name: '白名单', type:'white' }
  ])
  let carData = ref([
    { value: parseInt(200 * (Math.random()+1)), name: '月租车', type:'month' },
    { value: parseInt(100  * (Math.random()+1)), name: '临时车', type:'temp' }
  ])
  let alarmList = ref([]);

  // 人员统计
  let inCount = ref(0);
  let outCount = ref(0);
  let sumPerson = ref(0);

  // 车辆统计
  let inStop = ref(0);
  let outStop = ref(0);
  let remainStop = ref(0);
  let sumStop = ref(0);

  // 用水电量
  let lastMonthWeter = ref(0);
  let lastMonthWeterComp = ref(0);
  let yearWeter = ref(0);
  let lastMonthElectirc = ref(0);
  let lastMonthElectircComp = ref(0);
  let yearElectirc = ref(0);

  let slide1 = null;
  let slide2 = null;
  let slide3 = null;
  let slide4 = null;
  let weterTimer = null;
  let eleTimer = null;
  let currentSlide1 = ref(1);
  let currentSlide2 = ref(1);

  // 时间
  let week = ref('');
  let currentTime = ref('00:00:00');
  let currentDate = ref('xxxx-xx-xx');
  let updateTimer = null;

  onMounted(() => {
    login()
    timer = setInterval(init, 10000);
    // updateTimer = setInterval(updateTime, 1000);
    weterTimer = setInterval(toggleSlides1, 5000);
    eleTimer = setInterval(toggleSlides2, 3000);
  })

  onBeforeUnmount(() => {
    // 组件卸载前清除定时器
    if (timer) {
      clearInterval(timer);
      timer = null;
    }

    if (updateTimer) {
      clearInterval(updateTimer);
      updateTimer = null;
    }

    if (weterTimer) {
      clearInterval(weterTimer);
      weterTimer = null;
    }
    if (eleTimer) {
      clearInterval(eleTimer);
      eleTimer = null;
    }
  })

  const login = () => {
      postData("/user/account/login", {
        username: 'admin',
        password: '123456'
      }).then(data => {
        if (data.success) {
          localStorage.setItem('token', data.result.token)
          init()
        } else {
          this.$message.error(data.message)
        }
      })
  }

  const init = () => {
    getTransMethod()
    getPersonType()
    getCar()
    getDeviceTotal()
    getWeterMonth()
    getWeterDay()
    getElectricMonth()
    getElectricDay()
    getAlarmList()

    getRadomData()

    // 获取日期
    // updateTime()
  }

  const getRadomData = () => {
    // 人员统计
    inCount.value = Math.floor((Math.random()+1) * 500);
    outCount.value = Math.floor((Math.random()+1) * 200);
    sumPerson.value = inCount.value + outCount.value;

    // 车辆统计
    inStop.value = Math.floor((Math.random()+1) * 250);
    outStop.value = Math.floor((Math.random()+1) * 350);
    remainStop.value = Math.floor((Math.random()+1) * 100);
    sumStop.value = inStop.value + outStop.value;

    // 水电
    lastMonthWeter.value = Math.floor((Math.random()+1) * 100);
    lastMonthWeterComp.value = Math.floor(Math.random() * 11) - 10;
    yearWeter.value = Math.floor(Math.random() * 2000);

    lastMonthElectirc.value = Math.floor((Math.random()+1) * 500);
    lastMonthElectircComp.value = Math.floor(Math.random() * 21) - 10;
    yearElectirc.value = Math.floor(Math.random() * 500);

    screenPixel.value = window.screen.width

    // 水电消耗
    slide1 = document.querySelector('.slide-1');
    slide2 = document.querySelector('.slide-2');
    slide3 = document.querySelector('.slide-3');
    slide4 = document.querySelector('.slide-4');
  }

  function updateTime() {
    let date = new Date()
    let Y = date.getFullYear() + '-'
    let M = (date.getMonth() + 1 < 10 ? '0' + (date.getMonth() + 1) : date.getMonth() + 1) + '-'
    let D = (date.getDate() < 10 ? '0' + date.getDate() : date.getDate()) + ' '
    let h = (date.getHours() < 10 ? '0' + date.getHours() : date.getHours()) + ':'
    let m = (date.getMinutes() < 10 ? '0' + date.getMinutes() : date.getMinutes()) + ':'
    let s = date.getSeconds() < 10 ? '0' + date.getSeconds() : date.getSeconds()
    week.value = "星期" + "日一二三四五六".charAt(date.getDay());
    currentDate.value = Y + M + D
    currentTime.value = h + m + s
  }

  function toggleSlides1() {
      if (currentSlide1.value === 1) {
        slide1.classList.add('active');
        slide2.classList.add('active');
        currentSlide1.value = 2;
      } else {
        slide1.classList.remove('active');
        slide2.classList.remove('active');
        currentSlide1.value = 1;
      }
  }

  function toggleSlides2() {
      if (currentSlide2.value === 1) {
        slide3.classList.add('active');
        slide4.classList.add('active');
        currentSlide2.value = 2;
      } else {
        slide3.classList.remove('active');
        slide4.classList.remove('active');
        currentSlide2.value = 1;
      }
  }

  // 通行方式
  const getTransMethod = () => {
    let chartDom = document.getElementById('transMethodEle')
    if (!chartDom) return
    transMethodChart = echarts.init(chartDom)
    let option = null
    transMethodChart.clear()

    const data = transMethodData.value

    // 计算总和
    const total = data.reduce((sum, item) => sum + item.value, 0);

    option = {
      tooltip: {
        trigger: 'item'
      },
      legend: {
        orient: 'horizontal',
        top: 'bottom',
        y: '5%',
        x: '8%',
        icon: "circle",
        itemHeight: 4,
        itemWidth: 4,
        itemGap: 10,
        formatter: function(name) {
          const item = data.find(d => d.name === name);
          if (item) {
            const percent = ((item.value / total) * 100).toFixed(1);
            if (item.type=='qr') {
              return `{name|${name}} {percent1|${percent}%}`;
            } else if (item.type=='face') {
              return `{name|${name}} {percent2|${percent}%}`;
            } else {
              return `{name|${name}} {percent3|${percent}%}`;
            }
            
          }
          return name;
        },
        textStyle: {
          width: 80,    // 文本宽度
          overflow: 'break', // 超出宽度自动换行
          rich: {
            name: {
              color: '#B4C0CC'
            },
            percent1: {
              color: '#0783FA'
            },
            percent2: {
              color: '#FFD15C'
            },
            percent3: {
              color: '#91D5FF'
            }
          }
        }
      },
      color: ['#0783FA', '#FFD15C', '#91D5FF'],
      series: [
        {
          name: '通行方式',
          type: 'pie',
          roseType: 'area',
          center: ['50%', '30%'],
          radius: ['35%', '55%'],
          itemStyle: {},
          label: {
            show: false,
            position: 'center'
          },
          emphasis: {
            label: {
              show: true,
              fontSize: 14,
              fontWeight: 'bold'
            }
          },
          labelLine: {
            show: false
          },
          data: data
        }
      ]
    };
    option && transMethodChart.setOption(option); 
  }

  // 人员类型
  const getPersonType = () => {
    let chartDom = document.getElementById('personTypeEle')
    if (!chartDom) return
    personTypeChart = echarts.init(chartDom)
    let option = null
    personTypeChart.clear()

    const data = personTypeData.value

    // 计算总和
    const total = data.reduce((sum, item) => sum + item.value, 0);

    option = {
      tooltip: {
        trigger: 'item'
      },
      legend: {
        orient: 'horizontal',
        top: 'bottom',
        y: '5%',
        x: '8%',
        icon: "circle",
        itemHeight: 4,
        itemWidth: 4,
        itemGap: 10,
        formatter: function(name) {
          const item = data.find(d => d.name === name);
          if (item) {
            const percent = ((item.value / total) * 100).toFixed(1);
            if (item.type=='owner') {
              return `{name|${name}} {percent1|${percent}%}`;
            } else if (item.type=='visitor') {
              return `{name|${name}} {percent2|${percent}%}`;
            }  else if (item.type=='manager') {
              return `{name|${name}} {percent3|${percent}%}`;
            } else {
              return `{name|${name}} {percent4|${percent}%}`;
            }
            
          }
          return name;
        },
        textStyle: {
          width: 80,    // 文本宽度
          overflow: 'break', // 超出宽度自动换行
          rich: {
            name: {
              color: '#B4C0CC'
            },
            percent1: {
              color: '#0783FA'
            },
            percent2: {
              color: '#FFD15C'
            },
            percent3: {
              color: '#31E8B4'
            },
            percent4: {
              color: '#91D5FF'
            }
          }
        }
      },
      color: ['#0783FA', '#FFD15C', '#31E8B4', '#91D5FF'],
      series: [
        {
          name: '人员类型',
          type: 'pie',
          roseType: 'area',
          center: ['50%', '30%'],
          radius: ['35%', '55%'],
          itemStyle: {},
          label: {
            show: false,
            position: 'center'
          },
          emphasis: {
            label: {
              show: true,
              fontSize: 14,
              fontWeight: 'bold'
            }
          },
          labelLine: {
            show: false
          },
          data: data
        }
      ]
    };
    option && personTypeChart.setOption(option); 
  }

  // 今日车辆类型占比
  const getCar = () => {
    let chartDom = document.getElementById('carChartEle')
    if (!chartDom) return
    carChart = echarts.init(chartDom)
    let option = null
    carChart.clear()

    const data = carData.value

    // 计算总和
    const total = data.reduce((sum, item) => sum + item.value, 0);

    option = {
      tooltip: {
        trigger: 'item'
      },
      legend: {
        orient: 'vertical',
        x: 'right',
        y: '25%',
        x: '65%',
        icon: "circle",
        itemHeight: 4,
        itemWidth: 4,
        itemGap: 15,
        formatter: function(name) {
          const item = data.find(d => d.name === name);
          if (item) {
            const percent = ((item.value / total) * 100).toFixed(1);
            if (item.type=='month') {
              return `{name|${name}} \n{percent1|${percent}%}`;
            } else{
              return `{name|${name}} \n{percent2|${percent}%}`;
            }
            
          }
          return name;
        },
        textStyle: {
          rich: {
            name: {
              color: '#B4C0CC'
            },
            percent1: {
              color: '#0783FA'
            },
            percent2: {
              color: '#FFD15C'
            }
          }
        }
      },
      color: ['#0783FA', '#FFD15C'],
      series: [
        {
          name: '今日车辆类型占比',
          type: 'pie',
          center: ['31%', '51%'],
          radius: ['85%', '70%'],
          itemStyle: {
            borderRadius: [10, 0, 0, 10],  // 左上、右上、右下、左下圆角
            borderColor: '#000',   // 间隙颜色（通常与背景色相同）
            borderWidth: 3         // 间隙宽度
          },
          label: {
            show: true,
            position: 'center',
            formatter: [
              '{b|' + total + '}',
              '{a|车辆总数}'
            ].join('\n'),
            rich: {
              a: {
                fontSize: 12,
                color: '#B4C0CC',
                align: 'center'
              },
              b: {
