      "deviceName": "",
      "modelId": "",
      "categoryId": "",
      "pageNum": 1,
      "pageSize": 9999,
      "nodeTypes": [],
      "online": "",
      "userGroupId": ""
    }).then(data => {
      if (data.success) {
        deviceTotal.value = Number(data.result.total)
        const records = data.result.records || []
        deviceData = records
        if (records && records.length>0) {
          records.forEach((item) => {
            if (item.online === 1) {
              onlineCount.value++
            } else {
              offlineCount.value++
            }
          })
        }
        deviceData = [
          { value: onlineCount.value, name: '在线率', type:'on' },
          { value: offlineCount.value, name: '故障率', type:'off' },
        ]
        setDeviceChart(deviceData)
      } else {
        this.$message.error(data.message)
      }
    })
  }

  const setDeviceChart = (deviceData) => {
    let chartDom = document.getElementById('devCharts')
    if (!chartDom) return
    deviceChart = echarts.init(chartDom)
    let option = null
    deviceChart.clear()

    const data = deviceData
    // 计算总和
    const total = data.reduce((sum, item) => sum + item.value, 0);

    option = {
      tooltip: {
        trigger: 'item'
      },
      legend: {
        orient: 'vertical',
        y: '85%',
        x: '10%',
        icon: "circle",
        itemHeight: 4,
        itemWidth: 4,
        itemGap: 5,
        formatter: function(name) {
          const item = data.find(d => d.name === name);
          if (item) {
            const percent = ((item.value / total) * 100).toFixed(1);
            if (item.type=='on') {
              return `{name|${name}} {percent1|${percent}%}`;
            } else{
              return `{name|${name}} {percent2|${percent}%}`;
            }
            
          }
          return name;
        },
