  // 获取告警事件列表
  const getAlarmList = () => {
    alarmList = ref([])
    getData("/acs/center/list", {
      "msgCode": "",
      "level": "",
      "state": 0,
      "pageNum": 1,
      "pageSize": 5,
      "standardType": ""
    }).then(data => {
      if (data.success) {
        const result = data.result.records || []
        if (result.length>0) {
          result.forEach((item) => {
            alarmList.value.push(item)
          })
        }
      } else {
        this.$message.error(data.message)
      }
    })
  }

  function getLast7Days() {
      let dates = [];
      let currentDate = new Date();
      for (let i = 0; i < 7; i++) {
          let date = new Date(currentDate);
          date.setDate(date.getDate() - i); // 向前回溯i天
          dates.push(date);
      }
      return dates;
  }
  
  // 格式化日期
  function formatDate(date) {
      let d = new Date(date),
          month = '' + (d.getMonth() + 1),
          day = '' + d.getDate();
  
      // if (month.length < 2) month = '0' + month;
      // if (day.length < 2) day = '0' + day;
  
      return [month, day].join('.');
  }
