export const getCToken = (): void => {
  const socket = new WebSocket(import.meta.env.VITE_WS_URL);
  socket.onopen = () => {
    // 获取cToken
    sendToGetcToken(socket);
  };
  socket.onmessage = (event) => {
    // 解析获取的数据
    dataAnalysis(event.data);
  };
}

// blob转arraybuffer
const blobToArrayBuffer = (blob: Blob, callback: Function): void => {
  let reader = new FileReader();
  reader.onload = function () {
    return callback(this.result);
  };
  reader.readAsArrayBuffer(blob);
};

// 解析获取的数据
const dataAnalysis = (data: Blob): void => {
  var secretKey: string | ArrayBuffer | undefined;
  var reader = new FileReader();
  reader.readAsText(data, "utf-8");
  reader.onload = function () {
    secretKey = reader?.result?.slice(-8);
  };
  blobToArrayBuffer(data, (arrayBuffer: ArrayBuffer) => {
    let backData = new Uint8Array(arrayBuffer);
    if (backData[0] == 0xc0) {
      if (backData[8] == 1) {
        localStorage.setItem("cToken", secretKey as string);
      }
    }
  });
};

// 发送获取cToken的消息
export const sendToGetcToken = (socket: WebSocket): void => {
  let token = localStorage.getItem("token");
  let msgHeader = [];
  msgHeader[0] = 0xa0;
  let params = {
    ip: location.hostname,
    token: token,
  };
  let extData = JSON.stringify(params);
  let extDataLen = extData && extData.length > 8 ? extData.length : 0;
  if (extDataLen > 0) {
    for (let i = 0; i < 45 + extDataLen; i++) {
      if (i == 0) {
      } else if (i > 3 && i < 8) {
        msgHeader[i] = 0;
      } else if (i > 44) {
        msgHeader[i] = extData.charCodeAt(i - 45);
      } else {
        msgHeader[i] = 0x00;
      }
    }
  } else {
    for (let i = 0; i < 45; i++) {
      if (i == 0) {
      } else if (7 < i && i < 16) {
        msgHeader[i] = token?.charCodeAt(i - 8) || 0;
      } else {
        msgHeader[i] = 0x00;
      }
    }
  }
  let data = new ArrayBuffer(msgHeader.length);
  let dataView = new DataView(data);
  for (let i = 0; i < msgHeader.length; i++) {
    dataView.setUint8(i, msgHeader[i]);
  }
  dataView.setUint32(4, msgHeader.length - 45, true);
  let dataList = new Uint8Array(data);
  socket.send(dataList);
};