import axios from "axios";
import qs from 'qs'
import merge from 'lodash/merge'
 
// 使用环境变量来设置基础URL
const request = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL,
  timeout: 10000,
  headers: {
    "Content-type": "application/json;charset=utf-8"
  }
});
 
request.interceptors.request.use(config => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers['X-Authorization'] = `Bearer ${token}`;
    config.headers.token = token;
  }
  return config;
}, error => {
  console.error("Request error: ", error);
  return Promise.reject(error);
});
 
request.interceptors.response.use(response => {
  if (response.status === 200) {
    return response.data;
  } else {
    // 可以根据需要添加更多的错误处理
    console.error("Response error: ", response);
    return Promise.reject(new Error("Error with status code " + response.status));
  }
}, error => {
  // 对常见的HTTP错误进行处理
  if (error.response) {
    // 请求已发出，服务器回复状态码不在2xx范围
    console.error("Error status: ", error.response.status);
    // 根据返回的状态码进行不同的处理
    // 例如: if (error.response.status === 401) { // 处理登录过期 }
  } else {
    // 服务器连回应都没有返回
    console.error("Network error: ", error);
  }
  return Promise.reject(error);
});

/**
 * 请求地址处理
 * @param {*} actionName action方法名称
 */
request.adornUrl = (actionName) => {
  // 非生产环境 && 开启代理, 接口前缀统一使用[/proxyApi/]前缀做代理拦截!
  let url = ''
  if (process.env.NODE_ENV == 'production' && actionName.indexOf('http') < 0) {
    if (actionName.includes('wastels') || actionName.includes('wastehic')) {
      url = `/api/v2${actionName}`
    } else {
      url = `/api/v2/waste${actionName}`
    }
  } else {
    url = actionName
  }
  return url
}

/**
 * get请求参数处理
 * @param {*} params 参数对象
 * @param {*} openDefultParams 是否开启默认参数?
 */
request.adornParams = (params = {}, openDefultParams = false) => {
  var defaults = {
    t: new Date().getTime(),
  }
  return openDefultParams ? merge(defaults, params) : params
}

/**
 * post请求数据处理
 * @param {*} data 数据对象
 * @param {*} openDefultdata 是否开启默认数据?
 * @param {*} contentType 数据格式
 *  json: 'application/json; charset=utf-8'
 *  form: 'application/x-www-form-urlencoded; charset=utf-8'
 */
request.adornData = (data = {}, openDefultdata = false, contentType = 'json') => {
  var defaults = {
    t: new Date().getTime(),
  }
  data = openDefultdata ? merge(defaults, data) : data
  return contentType === 'json' ? JSON.stringify(data) : qs.stringify(data)
}

export default request
